BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'Ischemic Heart Disease' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'Ischemic Heart Disease', 'IHD spectrum, ACS patterns, NTG, reperfusion', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - Ischemic Heart Disease (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'Ischemic Heart Disease - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Ischemic Heart Disease note, which statement about "IHD definition" is most accurate?', 'According to the Ischemic Heart Disease note, which statement about "IHD definition" is most accurate?', '[{"id": "a", "text": "IHD always occurs without coronary flow limitation."}, {"id": "b", "text": "Unstable angina is always exertional and brief."}, {"id": "c", "text": "Unstable angina is managed only with home rest."}, {"id": "d", "text": "IHD is a spectrum rather than one single condition."}]'::jsonb, '["d"]'::jsonb, 'Correct because Ischemic heart disease is a group of conditions caused by reduced blood flow to the myocardium. Treat ischemic symptoms as perfusion mismatch until proven otherwise.', 'Ischemic Heart Disease - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Etiology" in Ischemic Heart Disease. Which statement is correct?', 'The nurse is reviewing "Etiology" in Ischemic Heart Disease. Which statement is correct?', '[{"id": "a", "text": "Only congenital defects cause IHD."}, {"id": "b", "text": "Different mechanisms change urgency and treatment strategy."}, {"id": "c", "text": "Emergency escalation is unnecessary because these findings are low risk."}, {"id": "d", "text": "Serial evaluation can be deferred to outpatient follow-up."}]'::jsonb, '["b"]'::jsonb, 'Correct because Major causes listed are atherosclerosis (most common), coronary vasospasm, and thrombosis. Different mechanisms change urgency and treatment strategy.', 'Ischemic Heart Disease - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Clinical spectrum" in Ischemic Heart Disease?', 'Which clinical judgment is most accurate regarding "Clinical spectrum" in Ischemic Heart Disease?', '[{"id": "a", "text": "Thrombolytics are routine first-line for stable angina."}, {"id": "b", "text": "RCA infarcts primarily produce lateral lead changes."}, {"id": "c", "text": "Stable angina is the most severe endpoint."}, {"id": "d", "text": "Unstable angina precedes infarction stages in spectrum."}]'::jsonb, '["d"]'::jsonb, 'Correct because The IHD spectrum is silent ischemia to stable angina, unstable angina, NSTEMI, and STEMI. Progression across spectrum indicates rising acuity and intervention urgency.', 'Ischemic Heart Disease - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Risk factors" in Ischemic Heart Disease?', 'In rapid prioritization, which statement is most consistent with "Risk factors" in Ischemic Heart Disease?', '[{"id": "a", "text": "Emergency escalation is unnecessary because these findings are low risk."}, {"id": "b", "text": "Unstable angina should be managed only with PRN NTG at home."}, {"id": "c", "text": "Risk-factor clustering should increase suspicion even with atypical presentations."}, {"id": "d", "text": "Only age under 30 is listed as risk."}]'::jsonb, '["c"]'::jsonb, 'Correct because Risk factors include HTN, diabetes, hyperlipidemia, smoking, obesity, family history, and age thresholds male >45/female >55. Risk-factor clustering should increase suspicion even with atypical presentations.', 'Ischemic Heart Disease - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "LAD territory" in Ischemic Heart Disease would the nurse recognize as correct?', 'Which conclusion about "LAD territory" in Ischemic Heart Disease would the nurse recognize as correct?', '[{"id": "a", "text": "Stable angina does not respond to rest."}, {"id": "b", "text": "LAD occlusion maps to V1–V4 anterior STEMI."}, {"id": "c", "text": "LAD infarct primarily appears in II, III, aVF."}, {"id": "d", "text": "STEMI is partial occlusion without ST changes."}]'::jsonb, '["b"]'::jsonb, 'Correct because LAD supplies anterior wall and septum; occlusion causes anterior STEMI in V1–V4 and has high LV failure risk. Anterior occlusion patterns require rapid reperfusion planning.', 'Ischemic Heart Disease - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Ischemic Heart Disease note, which statement about "LCX territory" is most accurate?', 'According to the Ischemic Heart Disease note, which statement about "LCX territory" is most accurate?', '[{"id": "a", "text": "Thrombolytics are delayed until day 2."}, {"id": "b", "text": "Variant angina has permanent ST depression."}, {"id": "c", "text": "LCX infarct localizes to V1–V4."}, {"id": "d", "text": "LCX can supply SA node in some patients."}]'::jsonb, '["d"]'::jsonb, 'Correct because LCX supplies lateral wall (and SA node in some); occlusion causes lateral MI in I, aVL, V5–V6. Lead localization should guide likely vessel involvement.', 'Ischemic Heart Disease - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "RCA territory" in Ischemic Heart Disease. Which statement is correct?', 'The nurse is reviewing "RCA territory" in Ischemic Heart Disease. Which statement is correct?', '[{"id": "a", "text": "Variant angina has permanent ST depression."}, {"id": "b", "text": "NSTEMI requires ST elevation to diagnose."}, {"id": "c", "text": "RCA infarcts primarily produce lateral lead changes."}, {"id": "d", "text": "Inferior STEMI leads are II, III, aVF for RCA."}]'::jsonb, '["d"]'::jsonb, 'Correct because RCA supplies right ventricle, inferior wall, and AV node in about 80%; occlusion causes inferior STEMI in II, III, aVF with AV blocks common. Inferior MI with conduction changes should raise concern for RCA involvement.', 'Ischemic Heart Disease - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Stable angina pattern" in Ischemic Heart Disease?', 'Which clinical judgment is most accurate regarding "Stable angina pattern" in Ischemic Heart Disease?', '[{"id": "a", "text": "Stable angina does not respond to rest."}, {"id": "b", "text": "Stable angina treatment excludes aspirin."}, {"id": "c", "text": "NSTEMI is treated with discharge only."}, {"id": "d", "text": "Duration is usually under 5 minutes."}]'::jsonb, '["d"]'::jsonb, 'Correct because Stable angina is predictable with exertion/stress, lasts less than 5 minutes, and resolves with rest. Predictable exertional pain suggests stable ischemia but still requires risk optimization.', 'Ischemic Heart Disease - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Unstable angina pattern" in Ischemic Heart Disease?', 'In rapid prioritization, which statement is most consistent with "Unstable angina pattern" in Ischemic Heart Disease?', '[{"id": "a", "text": "Unstable angina is always exertional and brief."}, {"id": "b", "text": "Treat unstable angina as high-risk ACS needing hospitalization."}, {"id": "c", "text": "Unstable angina should be managed only with PRN NTG at home."}, {"id": "d", "text": "Serial evaluation can be deferred to outpatient follow-up."}]'::jsonb, '["b"]'::jsonb, 'Correct because Unstable angina is unpredictable, can occur at rest/minimal activity, often lasts >20 minutes, and does not resolve easily. Treat unstable angina as high-risk ACS needing hospitalization.', 'Ischemic Heart Disease - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Variant angina" in Ischemic Heart Disease would the nurse recognize as correct?', 'Which conclusion about "Variant angina" in Ischemic Heart Disease would the nurse recognize as correct?', '[{"id": "a", "text": "Beta-blockers are preferred first-line."}, {"id": "b", "text": "Variant angina occurs at rest/night."}, {"id": "c", "text": "Unlimited NTG doses are allowed."}, {"id": "d", "text": "NTG should be repeated every 30 seconds."}]'::jsonb, '["b"]'::jsonb, 'Correct because Prinzmetal angina is due to coronary vasospasm, occurs at rest/night, and shows transient ST elevation. Differentiate vasospastic episodes from fixed plaque obstruction patterns.', 'Ischemic Heart Disease - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Ischemic Heart Disease note, which statement about "Stable angina treatment" is most accurate?', 'According to the Ischemic Heart Disease note, which statement about "Stable angina treatment" is most accurate?', '[{"id": "a", "text": "Thrombolytics are routine first-line for stable angina."}, {"id": "b", "text": "Emergency escalation is unnecessary because these findings are low risk."}, {"id": "c", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "d", "text": "Early symptom control and anti-ischemic therapy prevent escalation."}]'::jsonb, '["d"]'::jsonb, 'Correct because Stable angina treatment includes rest, SL nitroglycerin, beta-blockers, and aspirin. Early symptom control and anti-ischemic therapy prevent escalation.', 'Ischemic Heart Disease - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Unstable angina treatment" in Ischemic Heart Disease. Which statement is correct?', 'The nurse is reviewing "Unstable angina treatment" in Ischemic Heart Disease. Which statement is correct?', '[{"id": "a", "text": "Escalate quickly because unstable angina may progress to infarction."}, {"id": "b", "text": "Emergency escalation is unnecessary because these findings are low risk."}, {"id": "c", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "d", "text": "Unstable angina should be managed only with PRN NTG at home."}]'::jsonb, '["a"]'::jsonb, 'Correct because Unstable angina management includes hospitalization, anticoagulation, dual antiplatelet therapy, and early PCI. Escalate quickly because unstable angina may progress to infarction.', 'Ischemic Heart Disease - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "STEMI pathophysiology" in Ischemic Heart Disease?', 'Which clinical judgment is most accurate regarding "STEMI pathophysiology" in Ischemic Heart Disease?', '[{"id": "a", "text": "Complete occlusion requires immediate reperfusion timeline focus."}, {"id": "b", "text": "STEMI is partial occlusion without ST changes."}, {"id": "c", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "d", "text": "All chest pain patients need routine oxygen regardless of saturation."}]'::jsonb, '["a"]'::jsonb, 'Correct because STEMI is complete coronary occlusion with transmural infarction and ST elevation, with Q waves developing later. Complete occlusion requires immediate reperfusion timeline focus.', 'Ischemic Heart Disease - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "STEMI reperfusion target" in Ischemic Heart Disease?', 'In rapid prioritization, which statement is most consistent with "STEMI reperfusion target" in Ischemic Heart Disease?', '[{"id": "a", "text": "Reperfusion timing is urgent in STEMI."}, {"id": "b", "text": "Thrombolytics are delayed until day 2."}, {"id": "c", "text": "NTG should be given regardless of BP."}, {"id": "d", "text": "Standing position is preferred for NTG."}]'::jsonb, '["a"]'::jsonb, 'Correct because Primary PCI should occur within 90 minutes door-to-balloon; if unavailable, thrombolytics within 30 minutes are listed. Time-to-reperfusion drives myocardial salvage and outcomes.', 'Ischemic Heart Disease - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "NSTEMI profile" in Ischemic Heart Disease would the nurse recognize as correct?', 'Which conclusion about "NSTEMI profile" in Ischemic Heart Disease would the nurse recognize as correct?', '[{"id": "a", "text": "NSTEMI requires ST elevation to diagnose."}, {"id": "b", "text": "Statins are not part of post-MI care."}, {"id": "c", "text": "ST depression/T-wave inversion can occur."}, {"id": "d", "text": "NTG should be repeated every 30 seconds."}]'::jsonb, '["c"]'::jsonb, 'Correct because NSTEMI is partial occlusion or severe vasospasm with subendocardial infarction, ST depression/T inversion, and elevated troponin without ST elevation. No ST elevation does not mean low risk; troponin-positive NSTEMI still needs intervention.', 'Ischemic Heart Disease - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Ischemic Heart Disease note, which statement about "NSTEMI timing" is most accurate?', 'According to the Ischemic Heart Disease note, which statement about "NSTEMI timing" is most accurate?', '[{"id": "a", "text": "Emergency escalation is unnecessary because these findings are low risk."}, {"id": "b", "text": "NSTEMI is treated with discharge only."}, {"id": "c", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "d", "text": "Schedule timely invasive strategy while stabilizing medically."}]'::jsonb, '["d"]'::jsonb, 'Correct because NSTEMI treatment includes anticoagulation + dual antiplatelet and early PCI within 24–72 hours. Schedule timely invasive strategy while stabilizing medically.', 'Ischemic Heart Disease - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "NTG BP safety" in Ischemic Heart Disease. Which statement is correct?', 'The nurse is reviewing "NTG BP safety" in Ischemic Heart Disease. Which statement is correct?', '[{"id": "a", "text": "Prevent NTG-related hypotension and syncope during administration."}, {"id": "b", "text": "Emergency escalation is unnecessary because these findings are low risk."}, {"id": "c", "text": "All chest pain patients need routine oxygen regardless of saturation."}, {"id": "d", "text": "Standing position is preferred for NTG."}]'::jsonb, '["a"]'::jsonb, 'Correct because Before SL nitroglycerin, check BP and hold if systolic is <90 mmHg; patient should sit down. Prevent NTG-related hypotension and syncope during administration.', 'Ischemic Heart Disease - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "NTG dosing sequence" in Ischemic Heart Disease?', 'Which clinical judgment is most accurate regarding "NTG dosing sequence" in Ischemic Heart Disease?', '[{"id": "a", "text": "Aspirin should be swallowed whole and delayed."}, {"id": "b", "text": "NTG should be repeated every 30 seconds."}, {"id": "c", "text": "Follow timing strictly and escalate if pain persists."}, {"id": "d", "text": "Serial evaluation can be deferred to outpatient follow-up."}]'::jsonb, '["c"]'::jsonb, 'Correct because SL NTG is given every 5 minutes up to 3 doses for persistent angina. Follow timing strictly and escalate if pain persists.', 'Ischemic Heart Disease - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "NTG escalation" in Ischemic Heart Disease?', 'In rapid prioritization, which statement is most consistent with "NTG escalation" in Ischemic Heart Disease?', '[{"id": "a", "text": "Pain persistence after 3 doses is low concern."}, {"id": "b", "text": "Emergency activation follows 3 unrelieved doses."}, {"id": "c", "text": "Wait several hours after 3 doses before escalation."}, {"id": "d", "text": "Aspirin should be swallowed whole and delayed."}]'::jsonb, '["b"]'::jsonb, 'Correct because If pain remains after 3 doses, activate emergency response (call 911/STEMI protocol). Unrelieved pain after protocol doses signals possible infarction requiring immediate action.', 'Ischemic Heart Disease - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "NTG storage" in Ischemic Heart Disease would the nurse recognize as correct?', 'Which conclusion about "NTG storage" in Ischemic Heart Disease would the nurse recognize as correct?', '[{"id": "a", "text": "Statins are not part of post-MI care."}, {"id": "b", "text": "Loss of tongue burning suggests potency loss."}, {"id": "c", "text": "Only congenital defects cause IHD."}, {"id": "d", "text": "NTG should be stored in clear pill organizers."}]'::jsonb, '["b"]'::jsonb, 'Correct because NTG should be kept in original dark glass bottle, room temperature, replaced every 6 months or when tongue burning sensation disappears. Proper storage preserves potency for emergency symptom control.', 'Ischemic Heart Disease - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Ischemic Heart Disease note, which statement about "MONA oxygen rule" is most accurate?', 'According to the Ischemic Heart Disease note, which statement about "MONA oxygen rule" is most accurate?', '[{"id": "a", "text": "Stable angina is the most severe endpoint."}, {"id": "b", "text": "Oxygen is never used in ACS."}, {"id": "c", "text": "Troponin T returns to baseline in 2 hours."}, {"id": "d", "text": "Oxygen is part of MONA with indication limits."}]'::jsonb, '["d"]'::jsonb, 'Correct because Oxygen in MONA is indicated only if SpO2 is below 94% to avoid hyperoxia. Use oxygen selectively rather than automatically in all chest pain cases.', 'Ischemic Heart Disease - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "MONA aspirin detail" in Ischemic Heart Disease. Which statement is correct?', 'The nurse is reviewing "MONA aspirin detail" in Ischemic Heart Disease. Which statement is correct?', '[{"id": "a", "text": "Aspirin 325 mg is given immediately and chewed."}, {"id": "b", "text": "Troponin T returns to baseline in 2 hours."}, {"id": "c", "text": "Aspirin should be swallowed whole and delayed."}, {"id": "d", "text": "Aspirin is contraindicated in all ACS cases."}]'::jsonb, '["a"]'::jsonb, 'Correct because Aspirin 325 mg is given immediately and chewed. Immediate antiplatelet therapy is a frontline mortality-reduction step.', 'Ischemic Heart Disease - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Additional ACS medications" in Ischemic Heart Disease?', 'Which clinical judgment is most accurate regarding "Additional ACS medications" in Ischemic Heart Disease?', '[{"id": "a", "text": "Combine antithrombotic and cardioprotective therapies to reduce reinfarction and mortality."}, {"id": "b", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "c", "text": "Statins are not part of post-MI care."}, {"id": "d", "text": "Emergency escalation is unnecessary because these findings are low risk."}]'::jsonb, '["a"]'::jsonb, 'Correct because Additional therapies listed are DAPT (clopidogrel + aspirin), heparin, beta-blocker, ACE inhibitor, and statin. Combine antithrombotic and cardioprotective therapies to reduce reinfarction and mortality.', 'Ischemic Heart Disease - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Troponin I kinetics" in Ischemic Heart Disease?', 'In rapid prioritization, which statement is most consistent with "Troponin I kinetics" in Ischemic Heart Disease?', '[{"id": "a", "text": "Troponin I peaks around 12–24 hours."}, {"id": "b", "text": "LCX infarct localizes to V1–V4."}, {"id": "c", "text": "Only congenital defects cause IHD."}, {"id": "d", "text": "Troponin I normalizes within 12 hours."}]'::jsonb, '["a"]'::jsonb, 'Correct because Troponin I normal is <0.04 ng/mL, rises 3–6 hrs, peaks 12–24 hrs, and remains elevated 7–10 days. Use timing to interpret serial markers accurately.', 'Ischemic Heart Disease - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Troponin T kinetics" in Ischemic Heart Disease would the nurse recognize as correct?', 'Which conclusion about "Troponin T kinetics" in Ischemic Heart Disease would the nurse recognize as correct?', '[{"id": "a", "text": "Troponin T returns to baseline in 2 hours."}, {"id": "b", "text": "Troponin T is not used in MI workup."}, {"id": "c", "text": "Troponin T normal threshold is <0.01 ng/mL."}, {"id": "d", "text": "STEMI is unrelated to IHD spectrum."}]'::jsonb, '["c"]'::jsonb, 'Correct because Troponin T normal is <0.01 ng/mL, rises 3–6 hrs, peaks 12–24 hrs, and can stay elevated 10–14 days. Longer elevation duration affects interpretation in late presenters.', 'Ischemic Heart Disease - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Ischemic Heart Disease note, which statement about "NCLEX first action" is most accurate?', 'According to the Ischemic Heart Disease note, which statement about "NCLEX first action" is most accurate?', '[{"id": "a", "text": "NTG potency check precedes all acute actions."}, {"id": "b", "text": "Stable angina usually occurs at rest for >20 min."}, {"id": "c", "text": "Stable angina is the most severe endpoint."}, {"id": "d", "text": "Provider notification is part of first action."}]'::jsonb, '["d"]'::jsonb, 'Correct because For chest pain, first action is 12-lead EKG and provider notification; aspirin is immediate and chewed. Immediate rhythm/injury assessment plus antiplatelet action should not be delayed.', 'Ischemic Heart Disease - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "IHD definition" in Ischemic Heart Disease. Which statement is correct?', 'The nurse is reviewing "IHD definition" in Ischemic Heart Disease. Which statement is correct?', '[{"id": "a", "text": "Myocardial oxygen supply-demand mismatch is central."}, {"id": "b", "text": "IHD always occurs without coronary flow limitation."}, {"id": "c", "text": "Unstable angina is managed only with home rest."}, {"id": "d", "text": "Unstable angina is always exertional and brief."}]'::jsonb, '["a"]'::jsonb, 'Correct because Ischemic heart disease is a group of conditions caused by reduced blood flow to the myocardium. Treat ischemic symptoms as perfusion mismatch until proven otherwise.', 'Ischemic Heart Disease - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Etiology" in Ischemic Heart Disease?', 'Which clinical judgment is most accurate regarding "Etiology" in Ischemic Heart Disease?', '[{"id": "a", "text": "Only congenital defects cause IHD."}, {"id": "b", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "c", "text": "Different mechanisms change urgency and treatment strategy."}, {"id": "d", "text": "Emergency escalation is unnecessary because these findings are low risk."}]'::jsonb, '["c"]'::jsonb, 'Correct because Major causes listed are atherosclerosis (most common), coronary vasospasm, and thrombosis. Different mechanisms change urgency and treatment strategy.', 'Ischemic Heart Disease - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Clinical spectrum" in Ischemic Heart Disease?', 'In rapid prioritization, which statement is most consistent with "Clinical spectrum" in Ischemic Heart Disease?', '[{"id": "a", "text": "Unstable angina precedes infarction stages in spectrum."}, {"id": "b", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "c", "text": "Stable angina is the most severe endpoint."}, {"id": "d", "text": "Thrombolytics are routine first-line for stable angina."}]'::jsonb, '["a"]'::jsonb, 'Correct because The IHD spectrum is silent ischemia to stable angina, unstable angina, NSTEMI, and STEMI. Progression across spectrum indicates rising acuity and intervention urgency.', 'Ischemic Heart Disease - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Risk factors" in Ischemic Heart Disease would the nurse recognize as correct?', 'Which conclusion about "Risk factors" in Ischemic Heart Disease would the nurse recognize as correct?', '[{"id": "a", "text": "Emergency escalation is unnecessary because these findings are low risk."}, {"id": "b", "text": "Only age under 30 is listed as risk."}, {"id": "c", "text": "Unstable angina should be managed only with PRN NTG at home."}, {"id": "d", "text": "Risk factors include HTN, diabetes, hyperlipidemia, smoking, obesity, family history, and age thresholds male >45/female >55."}]'::jsonb, '["d"]'::jsonb, 'Correct because Risk factors include HTN, diabetes, hyperlipidemia, smoking, obesity, family history, and age thresholds male >45/female >55. Risk-factor clustering should increase suspicion even with atypical presentations.', 'Ischemic Heart Disease - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Ischemic Heart Disease note, which statement about "LAD territory" is most accurate?', 'According to the Ischemic Heart Disease note, which statement about "LAD territory" is most accurate?', '[{"id": "a", "text": "Anterior territory loss risks LV failure."}, {"id": "b", "text": "STEMI is partial occlusion without ST changes."}, {"id": "c", "text": "LAD infarct primarily appears in II, III, aVF."}, {"id": "d", "text": "Stable angina does not respond to rest."}]'::jsonb, '["a"]'::jsonb, 'Correct because LAD supplies anterior wall and septum; occlusion causes anterior STEMI in V1–V4 and has high LV failure risk. Anterior occlusion patterns require rapid reperfusion planning.', 'Ischemic Heart Disease - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "LCX territory" in Ischemic Heart Disease. Which statement is correct?', 'The nurse is reviewing "LCX territory" in Ischemic Heart Disease. Which statement is correct?', '[{"id": "a", "text": "LCX infarct localizes to V1–V4."}, {"id": "b", "text": "Unstable angina is always exertional and brief."}, {"id": "c", "text": "Lateral MI leads include I, aVL, V5, V6 for LCX."}, {"id": "d", "text": "Unstable angina is managed only with home rest."}]'::jsonb, '["c"]'::jsonb, 'Correct because LCX supplies lateral wall (and SA node in some); occlusion causes lateral MI in I, aVL, V5–V6. Lead localization should guide likely vessel involvement.', 'Ischemic Heart Disease - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "RCA territory" in Ischemic Heart Disease?', 'Which clinical judgment is most accurate regarding "RCA territory" in Ischemic Heart Disease?', '[{"id": "a", "text": "NSTEMI requires ST elevation to diagnose."}, {"id": "b", "text": "RCA supplies right ventricle/inferior wall."}, {"id": "c", "text": "Variant angina has permanent ST depression."}, {"id": "d", "text": "RCA infarcts primarily produce lateral lead changes."}]'::jsonb, '["b"]'::jsonb, 'Correct because RCA supplies right ventricle, inferior wall, and AV node in about 80%; occlusion causes inferior STEMI in II, III, aVF with AV blocks common. Inferior MI with conduction changes should raise concern for RCA involvement.', 'Ischemic Heart Disease - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Stable angina pattern" in Ischemic Heart Disease?', 'In rapid prioritization, which statement is most consistent with "Stable angina pattern" in Ischemic Heart Disease?', '[{"id": "a", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "b", "text": "Predictable exertional pain suggests stable ischemia but still requires risk optimization."}, {"id": "c", "text": "Stable angina usually occurs at rest for >20 min."}, {"id": "d", "text": "Emergency escalation is unnecessary because these findings are low risk."}]'::jsonb, '["b"]'::jsonb, 'Correct because Stable angina is predictable with exertion/stress, lasts less than 5 minutes, and resolves with rest. Predictable exertional pain suggests stable ischemia but still requires risk optimization.', 'Ischemic Heart Disease - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Unstable angina pattern" in Ischemic Heart Disease would the nurse recognize as correct?', 'Which conclusion about "Unstable angina pattern" in Ischemic Heart Disease would the nurse recognize as correct?', '[{"id": "a", "text": "Unstable angina should be managed only with PRN NTG at home."}, {"id": "b", "text": "Unstable angina is unpredictable, can occur at rest/minimal activity, often lasts >20 minutes, and does not resolve easily."}, {"id": "c", "text": "Unstable angina is always exertional and brief."}, {"id": "d", "text": "Emergency escalation is unnecessary because these findings are low risk."}]'::jsonb, '["b"]'::jsonb, 'Correct because Unstable angina is unpredictable, can occur at rest/minimal activity, often lasts >20 minutes, and does not resolve easily. Treat unstable angina as high-risk ACS needing hospitalization.', 'Ischemic Heart Disease - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Ischemic Heart Disease note, which statement about "Variant angina" is most accurate?', 'According to the Ischemic Heart Disease note, which statement about "Variant angina" is most accurate?', '[{"id": "a", "text": "Differentiate vasospastic episodes from fixed plaque obstruction patterns."}, {"id": "b", "text": "Emergency escalation is unnecessary because these findings are low risk."}, {"id": "c", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "d", "text": "Variant angina has permanent ST depression."}]'::jsonb, '["a"]'::jsonb, 'Correct because Prinzmetal angina is due to coronary vasospasm, occurs at rest/night, and shows transient ST elevation. Differentiate vasospastic episodes from fixed plaque obstruction patterns.', 'Ischemic Heart Disease - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Stable angina treatment" in Ischemic Heart Disease. Which statement is correct?', 'The nurse is reviewing "Stable angina treatment" in Ischemic Heart Disease. Which statement is correct?', '[{"id": "a", "text": "Pain persistence after 3 doses is low concern."}, {"id": "b", "text": "Rest is first response in stable episodes."}, {"id": "c", "text": "Thrombolytics are delayed until day 2."}, {"id": "d", "text": "Stable angina treatment excludes aspirin."}]'::jsonb, '["b"]'::jsonb, 'Correct because Stable angina treatment includes rest, SL nitroglycerin, beta-blockers, and aspirin. Early symptom control and anti-ischemic therapy prevent escalation.', 'Ischemic Heart Disease - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Unstable angina treatment" in Ischemic Heart Disease?', 'Which clinical judgment is most accurate regarding "Unstable angina treatment" in Ischemic Heart Disease?', '[{"id": "a", "text": "NSTEMI requires ST elevation to diagnose."}, {"id": "b", "text": "NTG should be stored in clear pill organizers."}, {"id": "c", "text": "Unstable angina should be managed only with PRN NTG at home."}, {"id": "d", "text": "Hospitalization is indicated in unstable angina."}]'::jsonb, '["d"]'::jsonb, 'Correct because Unstable angina management includes hospitalization, anticoagulation, dual antiplatelet therapy, and early PCI. Escalate quickly because unstable angina may progress to infarction.', 'Ischemic Heart Disease - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "STEMI pathophysiology" in Ischemic Heart Disease?', 'In rapid prioritization, which statement is most consistent with "STEMI pathophysiology" in Ischemic Heart Disease?', '[{"id": "a", "text": "STEMI is partial occlusion without ST changes."}, {"id": "b", "text": "Emergency escalation is unnecessary because these findings are low risk."}, {"id": "c", "text": "STEMI is complete coronary occlusion with transmural infarction and ST elevation, with Q waves developing later."}, {"id": "d", "text": "All chest pain patients need routine oxygen regardless of saturation."}]'::jsonb, '["c"]'::jsonb, 'Correct because STEMI is complete coronary occlusion with transmural infarction and ST elevation, with Q waves developing later. Complete occlusion requires immediate reperfusion timeline focus.', 'Ischemic Heart Disease - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "STEMI reperfusion target" in Ischemic Heart Disease would the nurse recognize as correct?', 'Which conclusion about "STEMI reperfusion target" in Ischemic Heart Disease would the nurse recognize as correct?', '[{"id": "a", "text": "Thrombolytics are delayed until day 2."}, {"id": "b", "text": "NTG should be given regardless of BP."}, {"id": "c", "text": "Door-to-balloon target is 90 minutes."}, {"id": "d", "text": "Standing position is preferred for NTG."}]'::jsonb, '["c"]'::jsonb, 'Correct because Primary PCI should occur within 90 minutes door-to-balloon; if unavailable, thrombolytics within 30 minutes are listed. Time-to-reperfusion drives myocardial salvage and outcomes.', 'Ischemic Heart Disease - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Ischemic Heart Disease note, which statement about "NSTEMI profile" is most accurate?', 'According to the Ischemic Heart Disease note, which statement about "NSTEMI profile" is most accurate?', '[{"id": "a", "text": "Emergency escalation is unnecessary because these findings are low risk."}, {"id": "b", "text": "No ST elevation does not mean low risk; troponin-positive NSTEMI still needs intervention."}, {"id": "c", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "d", "text": "NSTEMI requires ST elevation to diagnose."}]'::jsonb, '["b"]'::jsonb, 'Correct because NSTEMI is partial occlusion or severe vasospasm with subendocardial infarction, ST depression/T inversion, and elevated troponin without ST elevation. No ST elevation does not mean low risk; troponin-positive NSTEMI still needs intervention.', 'Ischemic Heart Disease - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "NSTEMI timing" in Ischemic Heart Disease. Which statement is correct?', 'The nurse is reviewing "NSTEMI timing" in Ischemic Heart Disease. Which statement is correct?', '[{"id": "a", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "b", "text": "NSTEMI is treated with discharge only."}, {"id": "c", "text": "NSTEMI treatment includes anticoagulation + dual antiplatelet and early PCI within 24–72 hours."}, {"id": "d", "text": "Emergency escalation is unnecessary because these findings are low risk."}]'::jsonb, '["c"]'::jsonb, 'Correct because NSTEMI treatment includes anticoagulation + dual antiplatelet and early PCI within 24–72 hours. Schedule timely invasive strategy while stabilizing medically.', 'Ischemic Heart Disease - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "NTG BP safety" in Ischemic Heart Disease?', 'Which clinical judgment is most accurate regarding "NTG BP safety" in Ischemic Heart Disease?', '[{"id": "a", "text": "Troponin T is not used in MI workup."}, {"id": "b", "text": "Standing position is preferred for NTG."}, {"id": "c", "text": "Hold NTG if systolic BP is under 90."}, {"id": "d", "text": "NTG should be given regardless of BP."}]'::jsonb, '["c"]'::jsonb, 'Correct because Before SL nitroglycerin, check BP and hold if systolic is <90 mmHg; patient should sit down. Prevent NTG-related hypotension and syncope during administration.', 'Ischemic Heart Disease - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "NTG dosing sequence" in Ischemic Heart Disease?', 'In rapid prioritization, which statement is most consistent with "NTG dosing sequence" in Ischemic Heart Disease?', '[{"id": "a", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "b", "text": "Persistent pain after sequential doses needs escalation."}, {"id": "c", "text": "NTG should be repeated every 30 seconds."}, {"id": "d", "text": "NTG potency check precedes all acute actions."}]'::jsonb, '["b"]'::jsonb, 'Correct because SL NTG is given every 5 minutes up to 3 doses for persistent angina. Follow timing strictly and escalate if pain persists.', 'Ischemic Heart Disease - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "NTG escalation" in Ischemic Heart Disease would the nurse recognize as correct?', 'Which conclusion about "NTG escalation" in Ischemic Heart Disease would the nurse recognize as correct?', '[{"id": "a", "text": "Pain persistence after 3 doses is low concern."}, {"id": "b", "text": "Persistent pain indicates possible acute MI."}, {"id": "c", "text": "Aspirin is contraindicated in all ACS cases."}, {"id": "d", "text": "Aspirin should be swallowed whole and delayed."}]'::jsonb, '["b"]'::jsonb, 'Correct because If pain remains after 3 doses, activate emergency response (call 911/STEMI protocol). Unrelieved pain after protocol doses signals possible infarction requiring immediate action.', 'Ischemic Heart Disease - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Ischemic Heart Disease note, which statement about "NTG storage" is most accurate?', 'According to the Ischemic Heart Disease note, which statement about "NTG storage" is most accurate?', '[{"id": "a", "text": "Potency is unaffected by storage."}, {"id": "b", "text": "Troponin I normalizes within 12 hours."}, {"id": "c", "text": "Dark glass bottle storage is specified."}, {"id": "d", "text": "Statins are not part of post-MI care."}]'::jsonb, '["c"]'::jsonb, 'Correct because NTG should be kept in original dark glass bottle, room temperature, replaced every 6 months or when tongue burning sensation disappears. Proper storage preserves potency for emergency symptom control.', 'Ischemic Heart Disease - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "MONA oxygen rule" in Ischemic Heart Disease. Which statement is correct?', 'The nurse is reviewing "MONA oxygen rule" in Ischemic Heart Disease. Which statement is correct?', '[{"id": "a", "text": "Serial evaluation can be deferred to outpatient follow-up."}, {"id": "b", "text": "All chest pain patients need routine oxygen regardless of saturation."}, {"id": "c", "text": "Oxygen in MONA is indicated only if SpO2 is below 94% to avoid hyperoxia."}, {"id": "d", "text": "Emergency escalation is unnecessary because these findings are low risk."}]'::jsonb, '["c"]'::jsonb, 'Correct because Oxygen in MONA is indicated only if SpO2 is below 94% to avoid hyperoxia. Use oxygen selectively rather than automatically in all chest pain cases.', 'Ischemic Heart Disease - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "MONA aspirin detail" in Ischemic Heart Disease?', 'Which clinical judgment is most accurate regarding "MONA aspirin detail" in Ischemic Heart Disease?', '[{"id": "a", "text": "Aspirin is part of first-line acute MI response."}, {"id": "b", "text": "NTG potency check precedes all acute actions."}, {"id": "c", "text": "Aspirin is contraindicated in all ACS cases."}, {"id": "d", "text": "Aspirin should be swallowed whole and delayed."}]'::jsonb, '["a"]'::jsonb, 'Correct because Aspirin 325 mg is given immediately and chewed. Immediate antiplatelet therapy is a frontline mortality-reduction step.', 'Ischemic Heart Disease - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Additional ACS medications" in Ischemic Heart Disease?', 'In rapid prioritization, which statement is most consistent with "Additional ACS medications" in Ischemic Heart Disease?', '[{"id": "a", "text": "Emergency escalation is unnecessary because these findings are low risk."}, {"id": "b", "text": "Combine antithrombotic and cardioprotective therapies to reduce reinfarction and mortality."}, {"id": "c", "text": "Statins are not part of post-MI care."}, {"id": "d", "text": "Serial evaluation can be deferred to outpatient follow-up."}]'::jsonb, '["b"]'::jsonb, 'Correct because Additional therapies listed are DAPT (clopidogrel + aspirin), heparin, beta-blocker, ACE inhibitor, and statin. Combine antithrombotic and cardioprotective therapies to reduce reinfarction and mortality.', 'Ischemic Heart Disease - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Troponin I kinetics" in Ischemic Heart Disease would the nurse recognize as correct?', 'Which conclusion about "Troponin I kinetics" in Ischemic Heart Disease would the nurse recognize as correct?', '[{"id": "a", "text": "Troponin I normalizes within 12 hours."}, {"id": "b", "text": "IHD is primarily pericardial inflammation."}, {"id": "c", "text": "IHD always occurs without coronary flow limitation."}, {"id": "d", "text": "Troponin I may remain elevated for 7–10 days."}]'::jsonb, '["d"]'::jsonb, 'Correct because Troponin I normal is <0.04 ng/mL, rises 3–6 hrs, peaks 12–24 hrs, and remains elevated 7–10 days. Use timing to interpret serial markers accurately.', 'Ischemic Heart Disease - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "IHD definition" in Ischemic Heart Disease are correct? (Select all that apply)', 'Which statements about "IHD definition" in Ischemic Heart Disease are correct? (Select all that apply)', '[{"id": "a", "text": "IHD is primarily pericardial inflammation."}, {"id": "b", "text": "Myocardial oxygen supply-demand mismatch is central."}, {"id": "c", "text": "IHD involves reduced myocardial perfusion."}, {"id": "d", "text": "IHD is a spectrum rather than one single condition."}, {"id": "e", "text": "IHD always occurs without coronary flow limitation."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Ischemic heart disease is a group of conditions caused by reduced blood flow to the myocardium.', 'Ischemic Heart Disease - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Ischemic Heart Disease, which findings or actions relate to "Etiology"? (Select all that apply)', 'For Ischemic Heart Disease, which findings or actions relate to "Etiology"? (Select all that apply)', '[{"id": "a", "text": "Vasospasm is excluded."}, {"id": "b", "text": "Coronary vasospasm is listed as a cause."}, {"id": "c", "text": "Only congenital defects cause IHD."}, {"id": "d", "text": "Thrombosis is listed as a cause."}, {"id": "e", "text": "Atherosclerosis is the most common cause listed."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Major causes listed are atherosclerosis (most common), coronary vasospasm, and thrombosis.', 'Ischemic Heart Disease - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Clinical spectrum" in Ischemic Heart Disease? (Select all that apply)', 'The nurse is planning care. Which items apply to "Clinical spectrum" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Silent ischemia can occur."}, {"id": "b", "text": "Unstable angina precedes infarction stages in spectrum."}, {"id": "c", "text": "STEMI is unrelated to IHD spectrum."}, {"id": "d", "text": "NSTEMI and STEMI are part of IHD spectrum."}, {"id": "e", "text": "Stable angina is the most severe endpoint."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: The IHD spectrum is silent ischemia to stable angina, unstable angina, NSTEMI, and STEMI.', 'Ischemic Heart Disease - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Risk factors" in Ischemic Heart Disease? (Select all that apply)', 'Which of the following are consistent with "Risk factors" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Hypertension and diabetes are listed risk factors."}, {"id": "b", "text": "Age thresholds are listed for men and women."}, {"id": "c", "text": "Smoking and obesity are listed risk factors."}, {"id": "d", "text": "Family history does not matter."}, {"id": "e", "text": "Only age under 30 is listed as risk."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Risk factors include HTN, diabetes, hyperlipidemia, smoking, obesity, family history, and age thresholds male >45/female >55.', 'Ischemic Heart Disease - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "LAD territory" in Ischemic Heart Disease? (Select all that apply)', 'During reassessment, which observations align with "LAD territory" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Anterior territory loss risks LV failure."}, {"id": "b", "text": "LAD infarct primarily appears in II, III, aVF."}, {"id": "c", "text": "LAD mainly supplies inferior wall."}, {"id": "d", "text": "LAD is called widow maker."}, {"id": "e", "text": "LAD occlusion maps to V1–V4 anterior STEMI."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: LAD supplies anterior wall and septum; occlusion causes anterior STEMI in V1–V4 and has high LV failure risk.', 'Ischemic Heart Disease - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "LCX territory" in Ischemic Heart Disease are correct? (Select all that apply)', 'Which statements about "LCX territory" in Ischemic Heart Disease are correct? (Select all that apply)', '[{"id": "a", "text": "LCX infarct localizes to V1–V4."}, {"id": "b", "text": "LCX always supplies AV node."}, {"id": "c", "text": "LCX is often non-dominant."}, {"id": "d", "text": "LCX can supply SA node in some patients."}, {"id": "e", "text": "Lateral MI leads include I, aVL, V5, V6 for LCX."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: LCX supplies lateral wall (and SA node in some); occlusion causes lateral MI in I, aVL, V5–V6.', 'Ischemic Heart Disease - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Ischemic Heart Disease, which findings or actions relate to "RCA territory"? (Select all that apply)', 'For Ischemic Heart Disease, which findings or actions relate to "RCA territory"? (Select all that apply)', '[{"id": "a", "text": "RCA infarcts primarily produce lateral lead changes."}, {"id": "b", "text": "Inferior STEMI leads are II, III, aVF for RCA."}, {"id": "c", "text": "RCA supplies right ventricle/inferior wall."}, {"id": "d", "text": "AV blocks are common with RCA MI."}, {"id": "e", "text": "AV block is rare with RCA MI."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: RCA supplies right ventricle, inferior wall, and AV node in about 80%; occlusion causes inferior STEMI in II, III, aVF with AV blocks common.', 'Ischemic Heart Disease - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Stable angina pattern" in Ischemic Heart Disease? (Select all that apply)', 'The nurse is planning care. Which items apply to "Stable angina pattern" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Stable angina is predictable."}, {"id": "b", "text": "Duration is usually under 5 minutes."}, {"id": "c", "text": "Stable angina usually occurs at rest for >20 min."}, {"id": "d", "text": "Rest commonly relieves symptoms."}, {"id": "e", "text": "Stable angina does not respond to rest."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Stable angina is predictable with exertion/stress, lasts less than 5 minutes, and resolves with rest.', 'Ischemic Heart Disease - NCLEX', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Unstable angina pattern" in Ischemic Heart Disease? (Select all that apply)', 'Which of the following are consistent with "Unstable angina pattern" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Early PCI strategy is listed for unstable angina."}, {"id": "b", "text": "Unstable angina may occur at rest."}, {"id": "c", "text": "Unstable angina is always exertional and brief."}, {"id": "d", "text": "Duration over 20 minutes is noted."}, {"id": "e", "text": "Unstable angina is managed only with home rest."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Unstable angina is unpredictable, can occur at rest/minimal activity, often lasts >20 minutes, and does not resolve easily.', 'Ischemic Heart Disease - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Variant angina" in Ischemic Heart Disease? (Select all that apply)', 'During reassessment, which observations align with "Variant angina" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Beta-blockers are preferred first-line."}, {"id": "b", "text": "Variant angina occurs at rest/night."}, {"id": "c", "text": "Variant angina has permanent ST depression."}, {"id": "d", "text": "CCBs and nitrates are listed therapy."}, {"id": "e", "text": "Transient ST elevation is described."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Prinzmetal angina is due to coronary vasospasm, occurs at rest/night, and shows transient ST elevation.', 'Ischemic Heart Disease - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Stable angina treatment" in Ischemic Heart Disease are correct? (Select all that apply)', 'Which statements about "Stable angina treatment" in Ischemic Heart Disease are correct? (Select all that apply)', '[{"id": "a", "text": "Rest is first response in stable episodes."}, {"id": "b", "text": "Beta-blockers and aspirin are listed in management."}, {"id": "c", "text": "Stable angina treatment excludes aspirin."}, {"id": "d", "text": "SL nitroglycerin is listed for stable episodes."}, {"id": "e", "text": "Thrombolytics are routine first-line for stable angina."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Stable angina treatment includes rest, SL nitroglycerin, beta-blockers, and aspirin.', 'Ischemic Heart Disease - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Ischemic Heart Disease, which findings or actions relate to "Unstable angina treatment"? (Select all that apply)', 'For Ischemic Heart Disease, which findings or actions relate to "Unstable angina treatment"? (Select all that apply)', '[{"id": "a", "text": "No antithrombotic therapy is used."}, {"id": "b", "text": "Unstable angina should be managed only with PRN NTG at home."}, {"id": "c", "text": "Hospitalization is indicated in unstable angina."}, {"id": "d", "text": "Dual antiplatelet and anticoagulation are listed."}, {"id": "e", "text": "Early PCI is part of management."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Unstable angina management includes hospitalization, anticoagulation, dual antiplatelet therapy, and early PCI.', 'Ischemic Heart Disease - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "STEMI pathophysiology" in Ischemic Heart Disease? (Select all that apply)', 'The nurse is planning care. Which items apply to "STEMI pathophysiology" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "ST elevation is present in STEMI."}, {"id": "b", "text": "STEMI is complete occlusion."}, {"id": "c", "text": "STEMI is subendocardial only."}, {"id": "d", "text": "STEMI is partial occlusion without ST changes."}, {"id": "e", "text": "Q waves may appear later in STEMI."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: STEMI is complete coronary occlusion with transmural infarction and ST elevation, with Q waves developing later.', 'Ischemic Heart Disease - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "STEMI reperfusion target" in Ischemic Heart Disease? (Select all that apply)', 'Which of the following are consistent with "STEMI reperfusion target" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Thrombolytics are delayed until day 2."}, {"id": "b", "text": "Door-to-balloon target is 90 minutes."}, {"id": "c", "text": "Thrombolytic target is 30 minutes if PCI unavailable."}, {"id": "d", "text": "STEMI PCI can wait 24 hours."}, {"id": "e", "text": "Reperfusion timing is urgent in STEMI."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Primary PCI should occur within 90 minutes door-to-balloon; if unavailable, thrombolytics within 30 minutes are listed.', 'Ischemic Heart Disease - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "NSTEMI profile" in Ischemic Heart Disease? (Select all that apply)', 'During reassessment, which observations align with "NSTEMI profile" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "NSTEMI has no ST elevation."}, {"id": "b", "text": "Troponin is elevated in NSTEMI."}, {"id": "c", "text": "NSTEMI troponin remains normal."}, {"id": "d", "text": "NSTEMI requires ST elevation to diagnose."}, {"id": "e", "text": "ST depression/T-wave inversion can occur."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: NSTEMI is partial occlusion or severe vasospasm with subendocardial infarction, ST depression/T inversion, and elevated troponin without ST elevation.', 'Ischemic Heart Disease - NCLEX', true, 65, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "NSTEMI timing" in Ischemic Heart Disease are correct? (Select all that apply)', 'Which statements about "NSTEMI timing" in Ischemic Heart Disease are correct? (Select all that apply)', '[{"id": "a", "text": "NSTEMI never receives PCI."}, {"id": "b", "text": "NSTEMI is treated with discharge only."}, {"id": "c", "text": "Early PCI window is 24–72 hours."}, {"id": "d", "text": "Dual antiplatelet is listed in NSTEMI care."}, {"id": "e", "text": "Anticoagulation is listed in NSTEMI care."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: NSTEMI treatment includes anticoagulation + dual antiplatelet and early PCI within 24–72 hours.', 'Ischemic Heart Disease - NCLEX', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Ischemic Heart Disease, which findings or actions relate to "NTG BP safety"? (Select all that apply)', 'For Ischemic Heart Disease, which findings or actions relate to "NTG BP safety"? (Select all that apply)', '[{"id": "a", "text": "BP check is step 1 in protocol."}, {"id": "b", "text": "Hold NTG if systolic BP is under 90."}, {"id": "c", "text": "Standing position is preferred for NTG."}, {"id": "d", "text": "NTG should be given regardless of BP."}, {"id": "e", "text": "Patient should be seated before dosing."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Before SL nitroglycerin, check BP and hold if systolic is <90 mmHg; patient should sit down.', 'Ischemic Heart Disease - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "NTG dosing sequence" in Ischemic Heart Disease? (Select all that apply)', 'The nurse is planning care. Which items apply to "NTG dosing sequence" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Dosing interval is 5 minutes."}, {"id": "b", "text": "NTG should be repeated every 30 seconds."}, {"id": "c", "text": "Maximum is 3 doses in protocol."}, {"id": "d", "text": "Unlimited NTG doses are allowed."}, {"id": "e", "text": "Persistent pain after sequential doses needs escalation."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: SL NTG is given every 5 minutes up to 3 doses for persistent angina.', 'Ischemic Heart Disease - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "NTG escalation" in Ischemic Heart Disease? (Select all that apply)', 'Which of the following are consistent with "NTG escalation" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Persistent pain indicates possible acute MI."}, {"id": "b", "text": "Escalation should not be delayed."}, {"id": "c", "text": "Pain persistence after 3 doses is low concern."}, {"id": "d", "text": "Wait several hours after 3 doses before escalation."}, {"id": "e", "text": "Emergency activation follows 3 unrelieved doses."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: If pain remains after 3 doses, activate emergency response (call 911/STEMI protocol).', 'Ischemic Heart Disease - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "NTG storage" in Ischemic Heart Disease? (Select all that apply)', 'During reassessment, which observations align with "NTG storage" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Loss of tongue burning suggests potency loss."}, {"id": "b", "text": "NTG should be stored in clear pill organizers."}, {"id": "c", "text": "Potency is unaffected by storage."}, {"id": "d", "text": "Replace every 6 months is listed."}, {"id": "e", "text": "Dark glass bottle storage is specified."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: NTG should be kept in original dark glass bottle, room temperature, replaced every 6 months or when tongue burning sensation disappears.', 'Ischemic Heart Disease - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "MONA oxygen rule" in Ischemic Heart Disease are correct? (Select all that apply)', 'Which statements about "MONA oxygen rule" in Ischemic Heart Disease are correct? (Select all that apply)', '[{"id": "a", "text": "Oxygen is never used in ACS."}, {"id": "b", "text": "Oxygen is part of MONA with indication limits."}, {"id": "c", "text": "Hyperoxia avoidance is emphasized."}, {"id": "d", "text": "Oxygen is conditional on SpO2 <94%."}, {"id": "e", "text": "All chest pain patients need routine oxygen regardless of saturation."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Oxygen in MONA is indicated only if SpO2 is below 94% to avoid hyperoxia.', 'Ischemic Heart Disease - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Ischemic Heart Disease, which findings or actions relate to "MONA aspirin detail"? (Select all that apply)', 'For Ischemic Heart Disease, which findings or actions relate to "MONA aspirin detail"? (Select all that apply)', '[{"id": "a", "text": "Aspirin is contraindicated in all ACS cases."}, {"id": "b", "text": "Aspirin should be swallowed whole and delayed."}, {"id": "c", "text": "Dose listed is 325 mg."}, {"id": "d", "text": "Aspirin is part of first-line acute MI response."}, {"id": "e", "text": "Aspirin should be chewed immediately."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Aspirin 325 mg is given immediately and chewed.', 'Ischemic Heart Disease - NCLEX', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Additional ACS medications" in Ischemic Heart Disease? (Select all that apply)', 'The nurse is planning care. Which items apply to "Additional ACS medications" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Heparin is listed for anticoagulation."}, {"id": "b", "text": "ACE inhibitor and statin are listed post-MI supports."}, {"id": "c", "text": "Heparin is avoided in all ACS."}, {"id": "d", "text": "Clopidogrel + aspirin is listed."}, {"id": "e", "text": "Statins are not part of post-MI care."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Additional therapies listed are DAPT (clopidogrel + aspirin), heparin, beta-blocker, ACE inhibitor, and statin.', 'Ischemic Heart Disease - NCLEX', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Troponin I kinetics" in Ischemic Heart Disease? (Select all that apply)', 'Which of the following are consistent with "Troponin I kinetics" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Troponin I normal is >5 ng/mL."}, {"id": "b", "text": "Troponin I may remain elevated for 7–10 days."}, {"id": "c", "text": "Troponin I peaks around 12–24 hours."}, {"id": "d", "text": "Troponin I rises at 3–6 hours."}, {"id": "e", "text": "Troponin I normalizes within 12 hours."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Troponin I normal is <0.04 ng/mL, rises 3–6 hrs, peaks 12–24 hrs, and remains elevated 7–10 days.', 'Ischemic Heart Disease - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Troponin T kinetics" in Ischemic Heart Disease? (Select all that apply)', 'During reassessment, which observations align with "Troponin T kinetics" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Rise and peak timing mirror early troponin response windows."}, {"id": "b", "text": "Troponin T returns to baseline in 2 hours."}, {"id": "c", "text": "Troponin T can stay elevated up to 10–14 days."}, {"id": "d", "text": "Troponin T normal threshold is <0.01 ng/mL."}, {"id": "e", "text": "Troponin T is not used in MI workup."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Troponin T normal is <0.01 ng/mL, rises 3–6 hrs, peaks 12–24 hrs, and can stay elevated 10–14 days.', 'Ischemic Heart Disease - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "NCLEX first action" in Ischemic Heart Disease are correct? (Select all that apply)', 'Which statements about "NCLEX first action" in Ischemic Heart Disease are correct? (Select all that apply)', '[{"id": "a", "text": "NTG potency check precedes all acute actions."}, {"id": "b", "text": "Provider notification is part of first action."}, {"id": "c", "text": "Delay EKG until after serial enzymes."}, {"id": "d", "text": "12-lead EKG within 10 minutes is listed."}, {"id": "e", "text": "Chewed aspirin is immediate in NCLEX tip."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: For chest pain, first action is 12-lead EKG and provider notification; aspirin is immediate and chewed.', 'Ischemic Heart Disease - NCLEX', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Ischemic Heart Disease, which findings or actions relate to "IHD definition"? (Select all that apply)', 'For Ischemic Heart Disease, which findings or actions relate to "IHD definition"? (Select all that apply)', '[{"id": "a", "text": "IHD is a spectrum rather than one single condition."}, {"id": "b", "text": "IHD is primarily pericardial inflammation."}, {"id": "c", "text": "Myocardial oxygen supply-demand mismatch is central."}, {"id": "d", "text": "IHD involves reduced myocardial perfusion."}, {"id": "e", "text": "IHD always occurs without coronary flow limitation."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Ischemic heart disease is a group of conditions caused by reduced blood flow to the myocardium.', 'Ischemic Heart Disease - NCLEX', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Etiology" in Ischemic Heart Disease? (Select all that apply)', 'The nurse is planning care. Which items apply to "Etiology" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Coronary vasospasm is listed as a cause."}, {"id": "b", "text": "Thrombosis is listed as a cause."}, {"id": "c", "text": "Only congenital defects cause IHD."}, {"id": "d", "text": "Vasospasm is excluded."}, {"id": "e", "text": "Atherosclerosis is the most common cause listed."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Major causes listed are atherosclerosis (most common), coronary vasospasm, and thrombosis.', 'Ischemic Heart Disease - NCLEX', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Clinical spectrum" in Ischemic Heart Disease? (Select all that apply)', 'Which of the following are consistent with "Clinical spectrum" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "STEMI is unrelated to IHD spectrum."}, {"id": "b", "text": "Silent ischemia can occur."}, {"id": "c", "text": "Stable angina is the most severe endpoint."}, {"id": "d", "text": "NSTEMI and STEMI are part of IHD spectrum."}, {"id": "e", "text": "Unstable angina precedes infarction stages in spectrum."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: The IHD spectrum is silent ischemia to stable angina, unstable angina, NSTEMI, and STEMI.', 'Ischemic Heart Disease - NCLEX', true, 79, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Risk factors" in Ischemic Heart Disease? (Select all that apply)', 'During reassessment, which observations align with "Risk factors" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Age thresholds are listed for men and women."}, {"id": "b", "text": "Smoking and obesity are listed risk factors."}, {"id": "c", "text": "Family history does not matter."}, {"id": "d", "text": "Hypertension and diabetes are listed risk factors."}, {"id": "e", "text": "Only age under 30 is listed as risk."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Risk factors include HTN, diabetes, hyperlipidemia, smoking, obesity, family history, and age thresholds male >45/female >55.', 'Ischemic Heart Disease - NCLEX', true, 80, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "LAD territory" in Ischemic Heart Disease are correct? (Select all that apply)', 'Which statements about "LAD territory" in Ischemic Heart Disease are correct? (Select all that apply)', '[{"id": "a", "text": "LAD occlusion maps to V1–V4 anterior STEMI."}, {"id": "b", "text": "Anterior territory loss risks LV failure."}, {"id": "c", "text": "LAD mainly supplies inferior wall."}, {"id": "d", "text": "LAD is called widow maker."}, {"id": "e", "text": "LAD infarct primarily appears in II, III, aVF."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: LAD supplies anterior wall and septum; occlusion causes anterior STEMI in V1–V4 and has high LV failure risk.', 'Ischemic Heart Disease - NCLEX', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Ischemic Heart Disease, which findings or actions relate to "LCX territory"? (Select all that apply)', 'For Ischemic Heart Disease, which findings or actions relate to "LCX territory"? (Select all that apply)', '[{"id": "a", "text": "LCX infarct localizes to V1–V4."}, {"id": "b", "text": "Lateral MI leads include I, aVL, V5, V6 for LCX."}, {"id": "c", "text": "LCX is often non-dominant."}, {"id": "d", "text": "LCX always supplies AV node."}, {"id": "e", "text": "LCX can supply SA node in some patients."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: LCX supplies lateral wall (and SA node in some); occlusion causes lateral MI in I, aVL, V5–V6.', 'Ischemic Heart Disease - NCLEX', true, 82, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "RCA territory" in Ischemic Heart Disease? (Select all that apply)', 'The nurse is planning care. Which items apply to "RCA territory" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Inferior STEMI leads are II, III, aVF for RCA."}, {"id": "b", "text": "AV block is rare with RCA MI."}, {"id": "c", "text": "RCA supplies right ventricle/inferior wall."}, {"id": "d", "text": "RCA infarcts primarily produce lateral lead changes."}, {"id": "e", "text": "AV blocks are common with RCA MI."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: RCA supplies right ventricle, inferior wall, and AV node in about 80%; occlusion causes inferior STEMI in II, III, aVF with AV blocks common.', 'Ischemic Heart Disease - NCLEX', true, 83, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Stable angina pattern" in Ischemic Heart Disease? (Select all that apply)', 'Which of the following are consistent with "Stable angina pattern" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Stable angina usually occurs at rest for >20 min."}, {"id": "b", "text": "Duration is usually under 5 minutes."}, {"id": "c", "text": "Stable angina does not respond to rest."}, {"id": "d", "text": "Rest commonly relieves symptoms."}, {"id": "e", "text": "Stable angina is predictable."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Stable angina is predictable with exertion/stress, lasts less than 5 minutes, and resolves with rest.', 'Ischemic Heart Disease - NCLEX', true, 84, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Unstable angina pattern" in Ischemic Heart Disease? (Select all that apply)', 'During reassessment, which observations align with "Unstable angina pattern" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Unstable angina is always exertional and brief."}, {"id": "b", "text": "Duration over 20 minutes is noted."}, {"id": "c", "text": "Unstable angina is managed only with home rest."}, {"id": "d", "text": "Early PCI strategy is listed for unstable angina."}, {"id": "e", "text": "Unstable angina may occur at rest."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Unstable angina is unpredictable, can occur at rest/minimal activity, often lasts >20 minutes, and does not resolve easily.', 'Ischemic Heart Disease - NCLEX', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Variant angina" in Ischemic Heart Disease are correct? (Select all that apply)', 'Which statements about "Variant angina" in Ischemic Heart Disease are correct? (Select all that apply)', '[{"id": "a", "text": "Variant angina occurs at rest/night."}, {"id": "b", "text": "Transient ST elevation is described."}, {"id": "c", "text": "Beta-blockers are preferred first-line."}, {"id": "d", "text": "Variant angina has permanent ST depression."}, {"id": "e", "text": "CCBs and nitrates are listed therapy."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Prinzmetal angina is due to coronary vasospasm, occurs at rest/night, and shows transient ST elevation.', 'Ischemic Heart Disease - NCLEX', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Ischemic Heart Disease, which findings or actions relate to "Stable angina treatment"? (Select all that apply)', 'For Ischemic Heart Disease, which findings or actions relate to "Stable angina treatment"? (Select all that apply)', '[{"id": "a", "text": "Beta-blockers and aspirin are listed in management."}, {"id": "b", "text": "Stable angina treatment excludes aspirin."}, {"id": "c", "text": "Thrombolytics are routine first-line for stable angina."}, {"id": "d", "text": "SL nitroglycerin is listed for stable episodes."}, {"id": "e", "text": "Rest is first response in stable episodes."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Stable angina treatment includes rest, SL nitroglycerin, beta-blockers, and aspirin.', 'Ischemic Heart Disease - NCLEX', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Unstable angina treatment" in Ischemic Heart Disease? (Select all that apply)', 'The nurse is planning care. Which items apply to "Unstable angina treatment" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Hospitalization is indicated in unstable angina."}, {"id": "b", "text": "Early PCI is part of management."}, {"id": "c", "text": "Dual antiplatelet and anticoagulation are listed."}, {"id": "d", "text": "No antithrombotic therapy is used."}, {"id": "e", "text": "Unstable angina should be managed only with PRN NTG at home."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Unstable angina management includes hospitalization, anticoagulation, dual antiplatelet therapy, and early PCI.', 'Ischemic Heart Disease - NCLEX', true, 88, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "STEMI pathophysiology" in Ischemic Heart Disease? (Select all that apply)', 'Which of the following are consistent with "STEMI pathophysiology" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "STEMI is partial occlusion without ST changes."}, {"id": "b", "text": "STEMI is complete occlusion."}, {"id": "c", "text": "ST elevation is present in STEMI."}, {"id": "d", "text": "STEMI is subendocardial only."}, {"id": "e", "text": "Q waves may appear later in STEMI."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: STEMI is complete coronary occlusion with transmural infarction and ST elevation, with Q waves developing later.', 'Ischemic Heart Disease - NCLEX', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "STEMI reperfusion target" in Ischemic Heart Disease? (Select all that apply)', 'During reassessment, which observations align with "STEMI reperfusion target" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Reperfusion timing is urgent in STEMI."}, {"id": "b", "text": "Door-to-balloon target is 90 minutes."}, {"id": "c", "text": "Thrombolytic target is 30 minutes if PCI unavailable."}, {"id": "d", "text": "Thrombolytics are delayed until day 2."}, {"id": "e", "text": "STEMI PCI can wait 24 hours."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Primary PCI should occur within 90 minutes door-to-balloon; if unavailable, thrombolytics within 30 minutes are listed.', 'Ischemic Heart Disease - NCLEX', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "NSTEMI profile" in Ischemic Heart Disease are correct? (Select all that apply)', 'Which statements about "NSTEMI profile" in Ischemic Heart Disease are correct? (Select all that apply)', '[{"id": "a", "text": "NSTEMI has no ST elevation."}, {"id": "b", "text": "NSTEMI requires ST elevation to diagnose."}, {"id": "c", "text": "ST depression/T-wave inversion can occur."}, {"id": "d", "text": "NSTEMI troponin remains normal."}, {"id": "e", "text": "Troponin is elevated in NSTEMI."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: NSTEMI is partial occlusion or severe vasospasm with subendocardial infarction, ST depression/T inversion, and elevated troponin without ST elevation.', 'Ischemic Heart Disease - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Ischemic Heart Disease, which findings or actions relate to "NSTEMI timing"? (Select all that apply)', 'For Ischemic Heart Disease, which findings or actions relate to "NSTEMI timing"? (Select all that apply)', '[{"id": "a", "text": "Early PCI window is 24–72 hours."}, {"id": "b", "text": "Dual antiplatelet is listed in NSTEMI care."}, {"id": "c", "text": "Anticoagulation is listed in NSTEMI care."}, {"id": "d", "text": "NSTEMI is treated with discharge only."}, {"id": "e", "text": "NSTEMI never receives PCI."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: NSTEMI treatment includes anticoagulation + dual antiplatelet and early PCI within 24–72 hours.', 'Ischemic Heart Disease - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "NTG BP safety" in Ischemic Heart Disease? (Select all that apply)', 'The nurse is planning care. Which items apply to "NTG BP safety" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "NTG should be given regardless of BP."}, {"id": "b", "text": "Hold NTG if systolic BP is under 90."}, {"id": "c", "text": "Patient should be seated before dosing."}, {"id": "d", "text": "BP check is step 1 in protocol."}, {"id": "e", "text": "Standing position is preferred for NTG."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Before SL nitroglycerin, check BP and hold if systolic is <90 mmHg; patient should sit down.', 'Ischemic Heart Disease - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "NTG dosing sequence" in Ischemic Heart Disease? (Select all that apply)', 'Which of the following are consistent with "NTG dosing sequence" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Persistent pain after sequential doses needs escalation."}, {"id": "b", "text": "Dosing interval is 5 minutes."}, {"id": "c", "text": "NTG should be repeated every 30 seconds."}, {"id": "d", "text": "Maximum is 3 doses in protocol."}, {"id": "e", "text": "Unlimited NTG doses are allowed."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: SL NTG is given every 5 minutes up to 3 doses for persistent angina.', 'Ischemic Heart Disease - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "NTG escalation" in Ischemic Heart Disease? (Select all that apply)', 'During reassessment, which observations align with "NTG escalation" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Pain persistence after 3 doses is low concern."}, {"id": "b", "text": "Emergency activation follows 3 unrelieved doses."}, {"id": "c", "text": "Escalation should not be delayed."}, {"id": "d", "text": "Wait several hours after 3 doses before escalation."}, {"id": "e", "text": "Persistent pain indicates possible acute MI."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: If pain remains after 3 doses, activate emergency response (call 911/STEMI protocol).', 'Ischemic Heart Disease - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "NTG storage" in Ischemic Heart Disease are correct? (Select all that apply)', 'Which statements about "NTG storage" in Ischemic Heart Disease are correct? (Select all that apply)', '[{"id": "a", "text": "Potency is unaffected by storage."}, {"id": "b", "text": "Loss of tongue burning suggests potency loss."}, {"id": "c", "text": "Replace every 6 months is listed."}, {"id": "d", "text": "Dark glass bottle storage is specified."}, {"id": "e", "text": "NTG should be stored in clear pill organizers."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: NTG should be kept in original dark glass bottle, room temperature, replaced every 6 months or when tongue burning sensation disappears.', 'Ischemic Heart Disease - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Ischemic Heart Disease, which findings or actions relate to "MONA oxygen rule"? (Select all that apply)', 'For Ischemic Heart Disease, which findings or actions relate to "MONA oxygen rule"? (Select all that apply)', '[{"id": "a", "text": "All chest pain patients need routine oxygen regardless of saturation."}, {"id": "b", "text": "Oxygen is never used in ACS."}, {"id": "c", "text": "Hyperoxia avoidance is emphasized."}, {"id": "d", "text": "Oxygen is part of MONA with indication limits."}, {"id": "e", "text": "Oxygen is conditional on SpO2 <94%."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Oxygen in MONA is indicated only if SpO2 is below 94% to avoid hyperoxia.', 'Ischemic Heart Disease - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "MONA aspirin detail" in Ischemic Heart Disease? (Select all that apply)', 'The nurse is planning care. Which items apply to "MONA aspirin detail" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Aspirin is contraindicated in all ACS cases."}, {"id": "b", "text": "Aspirin is part of first-line acute MI response."}, {"id": "c", "text": "Aspirin should be swallowed whole and delayed."}, {"id": "d", "text": "Aspirin should be chewed immediately."}, {"id": "e", "text": "Dose listed is 325 mg."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Aspirin 325 mg is given immediately and chewed.', 'Ischemic Heart Disease - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Additional ACS medications" in Ischemic Heart Disease? (Select all that apply)', 'Which of the following are consistent with "Additional ACS medications" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Heparin is listed for anticoagulation."}, {"id": "b", "text": "Clopidogrel + aspirin is listed."}, {"id": "c", "text": "Heparin is avoided in all ACS."}, {"id": "d", "text": "Statins are not part of post-MI care."}, {"id": "e", "text": "ACE inhibitor and statin are listed post-MI supports."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Additional therapies listed are DAPT (clopidogrel + aspirin), heparin, beta-blocker, ACE inhibitor, and statin.', 'Ischemic Heart Disease - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Troponin I kinetics" in Ischemic Heart Disease? (Select all that apply)', 'During reassessment, which observations align with "Troponin I kinetics" in Ischemic Heart Disease? (Select all that apply)', '[{"id": "a", "text": "Troponin I normalizes within 12 hours."}, {"id": "b", "text": "Troponin I rises at 3–6 hours."}, {"id": "c", "text": "Troponin I normal is >5 ng/mL."}, {"id": "d", "text": "Troponin I peaks around 12–24 hours."}, {"id": "e", "text": "Troponin I may remain elevated for 7–10 days."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Troponin I normal is <0.04 ng/mL, rises 3–6 hrs, peaks 12–24 hrs, and remains elevated 7–10 days.', 'Ischemic Heart Disease - NCLEX', true, 100, 1, true);
